#!/usr/bin/env python3
"""Controlled actual-game drone inspection and raw captures, plus a standalone model viewer."""
import json, base64
from pathlib import Path
from playwright.sync_api import sync_playwright
out = Path('docs/screenshots/drones'); checks = {}; errors = []; observations = {}
with sync_playwright() as p:
 b = p.chromium.launch(executable_path='/usr/bin/chromium', headless=True, args=['--no-sandbox','--enable-unsafe-swiftshader','--use-angle=swiftshader','--disable-dev-shm-usage'])
 page = b.new_page(viewport={'width':800,'height':720})
 page.on('pageerror', lambda e: errors.append(str(e)))
 page.on('console', lambda m: observations.setdefault('console', []).append(m.type+': '+m.text) if m.type=='error' else None)
 try:
  page.goto('http://127.0.0.1:5173/',wait_until='domcontentloaded'); page.locator('#newgame').wait_for(state='visible',timeout=120000); page.click('#newgame'); page.wait_for_function('game.started && document.pointerLockElement===game.canvas',timeout=60000)
  page.evaluate('''() => {const g=game, p=g.player.pos;window.initialGame=g;g.renderer.setAnimationLoop(null);g.qualityLevel=3;g.aoOn=false;g.shaftsOn=false;g.onResize();g.ao.configuration.intensity=0;g.step(.016);g.renderer.shadowMap.enabled=false;p.y+=50;const x=p.x,y=p.y+3,z=p.z;window.d1=g.entities.spawnEnemy('bat',x,y,z);window.d2=g.entities.spawnEnemy('bat',x+2,y,z);d1.walking=false;d2.walking=false;d1.updateSprite(0);d2.updateSprite(0);d2.model3d.visible=false;g.camera.position.set(d1.pos.x+1.8,d1.pos.y+1.5,d1.pos.z+3);g.camera.lookAt(d1.pos.x,d1.pos.y+.3,d1.pos.z);g.camera.updateMatrixWorld();}''')
  data=page.evaluate('''() => {const a=d1.model3d.children,b=d2.model3d.children;const eyes=a.filter(m=>m.material.emissive?.getHex()===0xff2816);const shell=a.filter(m=>m.material.map);const before=eyes.map(m=>[m.material.emissive.getHex(),m.material.emissiveIntensity]);d1.flash=.08;d1.updateSprite(.01);const after=eyes.map(m=>[m.material.emissive.getHex(),m.material.emissiveIntensity]);d1.walking=true;d1.animT=0;d1.updateSprite(.1);return {pos:d1.pos.toArray(), modelPos:d1.model3d.position.toArray(), modelVisible:d1.model3d.visible, camera:game.camera.position.toArray(), cameraDir:game.camera.getWorldDirection(d1.pos.clone()).toArray(), cameraLayers:game.camera.layers.mask, modelLayers:d1.model3d.layers.mask, meshCount:a.length, mappedParts:shell.length, mappedPartsHaveTexture:shell.every(m=>!!m.material.map), shareShell:shell[0].material===b[0].material && shell[0].material.map===b[0].material.map, pointLights:a.filter(m=>m.isPointLight).length, eyes:eyes.length, opticsBefore:before,opticsAfter:after,rotations:a.map(m=>m.rotation.x),flashAfter:d1.flash}}''')
  observations.update(data); checks['shell texture shared between two drones']=data['mappedParts']>=1 and data['shareShell']; checks['no per-drone point lights']=data['pointLights']==0; checks['optics survive flash update']=data['opticsBefore']==data['opticsAfter'] and data['eyes']==4; checks['walking preserves assembled parts']=all(v == 0 for v in data['rotations'])
  for label, tm in [('day', .5), ('night', 0)]:
   page.evaluate("""(tm) => {game.time=tm;game.updateDay(0);game.ui.update(0);game.camera.updateMatrixWorld();game.composer.render()}""", tm)
   page.screenshot(path=str(out/('game-'+label+'.png')),timeout=120000)
  diag=page.evaluate("""async () => {const T=await import('/node_modules/.vite/deps/three.js');const g=game,m=d1.model3d,c=g.camera;m.updateMatrixWorld(true);c.updateMatrixWorld(true);const box=new T.Box3().setFromObject(m), frustum=new T.Frustum().setFromProjectionMatrix(new T.Matrix4().multiplyMatrices(c.projectionMatrix,c.matrixWorldInverse));return {started:g.started,sameGame:g===window.initialGame,parentIsScene:m.parent===g.scene,parentVisible:m.parent.visible,worldPosition:m.getWorldPosition(new T.Vector3()).toArray(),bounds:[box.min.toArray(),box.max.toArray()],frustumIntersects:frustum.intersectsBox(box),near:c.near,far:c.far,allMaterialsVisible:m.children.every(x=>x.visible && x.material.visible),contextLost:g.renderer.getContext().isContextLost(),renderTarget:!!g.renderer.getRenderTarget()}}""")
  observations['cameraDiagnostic']=diag
  img=page.evaluate("""async () => {const T=await import('/node_modules/.vite/deps/three.js');const g=game,r=g.renderer,s=new T.Scene();s.background=new T.Color(0x778a9c);s.add(new T.AmbientLight(0xffffff,2));const l=new T.DirectionalLight(0xffffff,2);l.position.set(3,5,4);s.add(l);const m=d1.model3d.clone();m.position.set(0,0,0);m.rotation.set(0,0,0);m.scale.set(1,1,1);m.visible=true;s.add(m);const c=new T.PerspectiveCamera(40,800/720,.1,100);c.position.set(2,2,4);c.lookAt(0,0,0);r.setRenderTarget(null);r.setViewport(0,0,800,720);r.setScissorTest(false);r.state.reset();r.render(s,c);return g.canvas.toDataURL('image/png')}""")
  (out/'controlled-model-viewer.png').write_bytes(base64.b64decode(img.split(',')[1]))
 except Exception as e: errors.append(str(e))
 finally:
  (out/'results.json').write_text(json.dumps({'fixture':'Two bat enemies spawned; player moved 50 units above spawn; second hidden for framing. Game loop stopped. Game captures use game day/night lighting, a manually positioned camera and disabled shadows/AO; HUD overlaps part of model.', 'visual_capture':'Controlled standalone viewer uses cloned actual game model, same renderer, fixed camera, ambient and directional lights. Not gameplay.','checks':checks,'observations':observations,'errors':errors},indent=2)+'\n');b.close()
print(json.dumps({'checks':checks,'observations':observations,'errors':errors},indent=2))
if errors or not all(checks.values()): raise SystemExit(1)
